test('lateFee uses balance due, not total amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const payment = Math.floor(totals.total / 2);
  const partiallyPaid = recordPayment(issued, { amount: payment, date: '2026-10-15' }).value;

  const fee = lateFee(partiallyPaid, '2026-10-22');
  // 1 day overdue, fee based on remaining balance (half of total)
  const expected = Math.round((totals.total - payment) * 1 * 0.04 / 100);
  assert.equal(fee, expected);
});

