test('lateFee accumulates over multiple days', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);

  const fee10Days = lateFee(issued, '2026-10-25');
  const fee20Days = lateFee(issued, '2026-11-04');

  // fee should roughly double when days double
  assert.ok(fee20Days > fee10Days);
  assert.equal(fee20Days, Math.round(totals.total * 20 * 0.04 / 100));
});

